// Cloud vendor enum values (mirrors cloudvendor.proto)
export const enum CloudVendor {
  UNDEFINED = 0,
  AWS = 1,
  AZURE = 2,
  GCP = 3,
}

/** Timeout for IMDS HTTP requests in milliseconds. */
const IMDS_TIMEOUT_MS = 2000;

/** Timeout for token exchange RPCs in milliseconds. */
const EXCHANGE_TIMEOUT_MS = 10000;

// ---------------------------------------------------------------------------
// Cloud detection
// ---------------------------------------------------------------------------

/**
 * Probes cloud metadata endpoints to determine which cloud environment
 * the process is running in. Only uses metadata service endpoints.
 */
export async function detectCloud(): Promise<CloudVendor> {
  // 1. GCP: metadata server with Google-specific header
  try {
    const resp = await httpRequest("GET", "http://169.254.169.254/", {
      "Metadata-Flavor": "Google",
    });
    if (
      resp.statusCode === 200 &&
      resp.headers["metadata-flavor"] === "Google"
    ) {
      return CloudVendor.GCP;
    }
  } catch {
    /* not GCP */
  }

  // 2. Azure: instance metadata with Azure-specific header
  try {
    const resp = await httpRequest(
      "GET",
      "http://169.254.169.254/metadata/instance?api-version=2021-02-01",
      { Metadata: "true" },
    );
    if (resp.statusCode === 200) {
      return CloudVendor.AZURE;
    }
  } catch {
    /* not Azure */
  }

  // 3. AWS: IMDSv2 session token (preferred)
  try {
    const resp = await httpRequest(
      "PUT",
      "http://169.254.169.254/latest/api/token",
      { "X-aws-ec2-metadata-token-ttl-seconds": "21600" },
    );
    if (resp.statusCode === 200) {
      return CloudVendor.AWS;
    }
  } catch {
    /* not IMDSv2 */
  }

  // 4. AWS: IMDSv1 fallback
  try {
    const resp = await httpRequest(
      "GET",
      "http://169.254.169.254/latest/meta-data/",
      {},
    );
    if (resp.statusCode === 200) {
      return CloudVendor.AWS;
    }
  } catch {
    /* not IMDSv1 */
  }

  // 5. AWS EKS IRSA: projected service account token
  if (process.env["AWS_WEB_IDENTITY_TOKEN_FILE"]) {
    return CloudVendor.AWS;
  }

  throw new Error("no cloud metadata service detected (tried GCP, Azure, AWS)");
}

