interface SimpleResponse {
  statusCode: number;
  headers: Record<string, string>;
  body: string;
}

function httpRequest(
  method: string,
  urlStr: string,
  headers: Record<string, string>,
  body?: string,
): Promise<SimpleResponse> {
  return new Promise((resolve, reject) => {
    const url = new URL(urlStr);
    const isHttps = url.protocol === "https:";
    const options: http.RequestOptions = {
      method,
      hostname: url.hostname,
      port: url.port || (isHttps ? 443 : 80),
      path: url.pathname + url.search,
      headers,
      timeout: IMDS_TIMEOUT_MS,
    };

    const handler = (res: http.IncomingMessage) => {
      const chunks: Buffer[] = [];
      res.on("data", (chunk: Buffer) => chunks.push(chunk));
      res.on("end", () => {
        const hdrs: Record<string, string> = {};
        for (const [k, v] of Object.entries(res.headers)) {
          if (typeof v === "string") hdrs[k.toLowerCase()] = v;
          else if (Array.isArray(v)) hdrs[k.toLowerCase()] = v[0];
        }
        resolve({
          statusCode: res.statusCode || 0,
          headers: hdrs,
          body: Buffer.concat(chunks).toString("utf8"),
        });
      });
      res.on("error", reject);
    };

    const req = isHttps
      ? https.request(options, handler)
      : http.request(options, handler);
    req.on("error", reject);
    req.on("timeout", () => {
      req.destroy();
      reject(new Error("timeout"));
    });
    if (body) req.write(body);
    req.end();
  });
}

