interface AWSCredentials {
  accessKey: string;
  secretKey: string;
  sessionToken: string;
}

/** Fetches IAM role credentials from the EC2 IMDS (v2). */
async function awsIMDSCredentials(): Promise<AWSCredentials> {
  // Get IMDSv2 session token
  const tokenResp = await httpRequest(
    "PUT",
    "http://169.254.169.254/latest/api/token",
    { "X-aws-ec2-metadata-token-ttl-seconds": "21600" },
  );
  const imdsToken = tokenResp.body.trim();

  // Get IAM role name
  const roleResp = await httpRequest(
    "GET",
    "http://169.254.169.254/latest/meta-data/iam/security-credentials/",
    { "X-aws-ec2-metadata-token": imdsToken },
  );
  const roleName = roleResp.body.trim();
  if (!roleName) throw new Error("no IAM role attached to instance");

  // Get credentials for the role
  const credResp = await httpRequest(
    "GET",
    `http://169.254.169.254/latest/meta-data/iam/security-credentials/${roleName}`,
    { "X-aws-ec2-metadata-token": imdsToken },
  );

  const accessKey = extractJSONString(credResp.body, "AccessKeyId");
  const secretKey = extractJSONString(credResp.body, "SecretAccessKey");
  const sessionToken = extractJSONString(credResp.body, "Token");
  if (!accessKey || !secretKey)
    throw new Error("failed to parse IMDS credentials");
  return { accessKey, secretKey, sessionToken };
}

/** Reads credentials from EKS IRSA (projected service account token). */
async function awsEKSCredentials(): Promise<AWSCredentials> {
  const tokenFile = process.env["AWS_WEB_IDENTITY_TOKEN_FILE"] || "";
  const roleArn = process.env["AWS_ROLE_ARN"] || "";
  if (!tokenFile || !roleArn) {
    throw new Error("AWS_WEB_IDENTITY_TOKEN_FILE or AWS_ROLE_ARN not set");
  }
  const webToken = fs.readFileSync(tokenFile, "utf8").trim();

  let region =
    process.env["AWS_REGION"] ||
    process.env["AWS_DEFAULT_REGION"] ||
    "us-east-1";

  const stsURL = `https://sts.${region}.amazonaws.com/`;
  const body = new URLSearchParams({
    Action: "AssumeRoleWithWebIdentity",
    Version: "2011-06-15",
    RoleArn: roleArn,
    RoleSessionName: "servicemanager",
    WebIdentityToken: webToken,
  }).toString();

  const resp = await httpRequest(
    "POST",
    stsURL,
    { "Content-Type": "application/x-www-form-urlencoded" },
    body,
  );

  const accessKey = extractXMLValue(resp.body, "AccessKeyId");
  const secretKey = extractXMLValue(resp.body, "SecretAccessKey");
  const sessionToken = extractXMLValue(resp.body, "SessionToken");
  if (!accessKey || !secretKey) {
    throw new Error("failed to parse STS AssumeRoleWithWebIdentity response");
  }
  return { accessKey, secretKey, sessionToken };
}

// ---------------------------------------------------------------------------
// AWS SigV4 signing
// ---------------------------------------------------------------------------

function hmacSHA256(key: Buffer | string, data: string): Buffer {
  return crypto.createHmac("sha256", key).update(data, "utf8").digest();
}

function sha256Hex(data: string): string {
  return crypto.createHash("sha256").update(data, "utf8").digest("hex");
}

/**
 * Signs an HTTP request using AWS Signature Version 4.
 * Returns the signed headers map (including Authorization).
 */
function awsSignV4(
  method: string,
  urlStr: string,
  body: string,
  accessKey: string,
  secretKey: string,
  sessionToken: string,
  region: string,
  service: string,
  now: Date,
): Record<string, string> {
  const url = new URL(urlStr);
  const datestamp = now.toISOString().replace(/[-:T]/g, "").slice(0, 8);
  const amzDate = now
    .toISOString()
    .replace(/[-:]/g, "")
    .replace(/\.\d{3}Z$/, "Z");

  const payloadHash = sha256Hex(body);

  const headers: Record<string, string> = {
    host: url.host,
    "x-amz-date": amzDate,
    "x-amz-content-sha256": payloadHash,
    "content-type": "application/x-www-form-urlencoded; charset=utf-8",
  };
  if (sessionToken) {
    headers["x-amz-security-token"] = sessionToken;
  }

  const signedHeaderNames = Object.keys(headers).sort();
  const signedHeaders = signedHeaderNames.join(";");

  let canonicalHeaders = "";
  for (const k of signedHeaderNames) {
    canonicalHeaders += `${k}:${headers[k].trim()}\n`;
  }

  const canonicalRequest = [
    method,
    url.pathname,
    url.search.replace(/^\?/, ""),
    canonicalHeaders,
    signedHeaders,
    payloadHash,
  ].join("\n");

  const credentialScope = [datestamp, region, service, "aws4_request"].join(
    "/",
  );

  const stringToSign = [
    "AWS4-HMAC-SHA256",
    amzDate,
    credentialScope,
    sha256Hex(canonicalRequest),
  ].join("\n");

  // Signing key derivation
  const kDate = hmacSHA256("AWS4" + secretKey, datestamp);
  const kRegion = hmacSHA256(kDate, region);
  const kService = hmacSHA256(kRegion, service);
  const signingKey = hmacSHA256(kService, "aws4_request");

  const signature = hmacSHA256(signingKey, stringToSign).toString("hex");

  const authHeader = `AWS4-HMAC-SHA256 Credential=${accessKey}/${credentialScope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;

  return { ...headers, authorization: authHeader };
}

