interface PresignedHttpRequest {
  method: string;
  url: string;
  headers: Record<string, string>;
  body: string;
}

interface CloudIdentityProof {
  vendor: CloudVendor;
  presignedRequest?: PresignedHttpRequest;
  identityToken?: string;
}

/** Creates a CloudIdentityProof with a presigned STS GetCallerIdentity request. */
async function buildAWSCloudProof(): Promise<CloudIdentityProof> {
  let creds: AWSCredentials;
  if (process.env["AWS_WEB_IDENTITY_TOKEN_FILE"]) {
    creds = await awsEKSCredentials();
  } else {
    creds = await awsIMDSCredentials();
  }

  let region =
    process.env["AWS_REGION"] ||
    process.env["AWS_DEFAULT_REGION"] ||
    "us-east-1";
  const stsURL = `https://sts.${region}.amazonaws.com/`;
  const body = "Action=GetCallerIdentity&Version=2011-06-15";
  const now = new Date();

  const signedHeaders = awsSignV4(
    "POST",
    stsURL,
    body,
    creds.accessKey,
    creds.secretKey,
    creds.sessionToken,
    region,
    "sts",
    now,
  );

  return {
    vendor: CloudVendor.AWS,
    presignedRequest: {
      method: "POST",
      url: stsURL,
      headers: signedHeaders,
      body,
    },
  };
}

/** Fetches an identity token from the GCP metadata server. */
async function buildGCPCloudProof(
  audience: string,
): Promise<CloudIdentityProof> {
  const metadataURL = `http://metadata.google.internal/computeMetadata/v1/instance/service-accounts/default/identity?audience=${encodeURIComponent(audience)}&format=full`;

  const resp = await httpRequest("GET", metadataURL, {
    "Metadata-Flavor": "Google",
  });
  if (resp.statusCode !== 200) {
    throw new Error(`GCP metadata returned ${resp.statusCode}: ${resp.body}`);
  }

  return {
    vendor: CloudVendor.GCP,
    identityToken: resp.body.trim(),
  };
}

/** Fetches a managed identity token from the Azure IMDS. */
async function buildAzureCloudProof(
  resource: string,
): Promise<CloudIdentityProof> {
  const metadataURL = `http://169.254.169.254/metadata/identity/oauth2/token?api-version=2018-02-01&resource=${encodeURIComponent(resource)}`;

  const resp = await httpRequest("GET", metadataURL, { Metadata: "true" });
  if (resp.statusCode !== 200) {
    throw new Error(`Azure IMDS returned ${resp.statusCode}: ${resp.body}`);
  }

  const token = extractJSONString(resp.body, "access_token");
  if (!token) throw new Error("Azure IMDS response missing access_token");

  return {
    vendor: CloudVendor.AZURE,
    identityToken: token,
  };
}

// ---------------------------------------------------------------------------
// JSON/XML extraction helpers
// ---------------------------------------------------------------------------

function extractJSONString(json: string, key: string): string {
  const needle = `"${key}"`;
  const idx = json.indexOf(needle);
  if (idx < 0) return "";
  let rest = json.slice(idx + needle.length);
  rest = rest.replace(/^[\s:]+/, "");
  if (!rest.startsWith('"')) return "";
  rest = rest.slice(1);
  const end = rest.indexOf('"');
  if (end < 0) return "";
  return rest.slice(0, end);
}

function extractXMLValue(xml: string, key: string): string {
  const start = `<${key}>`;
  const end = `</${key}>`;
  const idx = xml.indexOf(start);
  if (idx < 0) return "";
  const rest = xml.slice(idx + start.length);
  const endIdx = rest.indexOf(end);
  if (endIdx < 0) return "";
  return rest.slice(0, endIdx);
}

// ---------------------------------------------------------------------------
// CloudTokenMinter
// ---------------------------------------------------------------------------

/**
 * CloudTokenMinter handles cloud-native token exchange:
 *  1. Builds a CloudIdentityProof (AWS presigned STS / GCP identity token / Azure managed identity)
 *  2. Sends it to TokenExchangerService.ExchangeToken to get a refresh token
 *  3. Exchanges the refresh token for an access token with the correct audience
 *  4. Caches and refreshes using half-life randomized renewal
 */
export class CloudTokenMinter {
  private readonly _vendor: CloudVendor;
  private readonly _serviceAudience: string;
  private _current = "";
  private _exp = 0;
  private _refreshTok = "";
  private _refreshExp = 0;
  private _refreshIat = 0;
  private _instanceId = "";
  private _exchChannel: grpc.Channel | null = null;
  private _exchClient: any = null;
  private _renewTimer: ReturnType<typeof setTimeout> | null = null;

  constructor(vendor: CloudVendor, serviceAudience: string) {
    this._vendor = vendor;
    this._serviceAudience = serviceAudience;
  }

  /** Sets the gRPC channel for token exchange. */
  setChannel(channel: grpc.Channel): void {
    this._exchChannel = channel;
  }

  /** Sets the TokenExchangerService gRPC client. */
  setExchClient(client: any): void {
    this._exchClient = client;
  }

  /** Returns the server-assigned instance ID. */
  get instanceId(): string {
    return this._instanceId;
  }

  /** Returns a valid bearer token. Performs token exchange if needed. */
  async getToken(): Promise<string> {
    const nowSecs = Math.floor(Date.now() / 1000);

    // Return cached access token if still valid (60s buffer)
    if (this._current && nowSecs + 60 < this._exp) {
      return this._current;
    }

    // Try refresh -> access exchange if we have a valid refresh token
    if (this._refreshTok && nowSecs < this._refreshExp) {
      try {
        return await this._doAccessExchange();
      } catch {
        // Fall through to full cloud proof exchange
      }
    }

    // Full cloud proof exchange
    await this._doCloudExchange();
    return this._doAccessExchange();
  }

  /** Clears cached tokens, forcing re-exchange. */
  invalidate(): void {
    this._current = "";
    this._exp = 0;
    this._refreshTok = "";
    this._refreshExp = 0;
    if (this._renewTimer) {
      clearTimeout(this._renewTimer);
      this._renewTimer = null;
    }
  }

  /** Stops the renewal timer. */
  close(): void {
    if (this._renewTimer) {
      clearTimeout(this._renewTimer);
      this._renewTimer = null;
    }
  }

  /** Builds a cloud proof and exchanges it for a refresh token. */
  private async _doCloudExchange(): Promise<void> {
    const proof = await this._buildProof();

    if (!this._exchClient) {
      throw new Error("token exchange client not initialized");
    }

    const req: any = { cloud_proof: this._proofToProto(proof) };
    // If we have an unexpired refresh token, include it as continuity_token
    if (this._refreshTok && Math.floor(Date.now() / 1000) < this._refreshExp) {
      req.continuity_token = this._refreshTok;
    }

    const resp = await this._exchangeToken(req);

    this._refreshTok = resp.base64 || "";
    this._refreshIat = Math.floor(Date.now() / 1000);
    if (resp.payload?.fields) {
      if (resp.payload.fields.exp) {
        this._refreshExp = resp.payload.fields.exp.number_value || 0;
      }
      if (resp.payload.fields.instance_id) {
        this._instanceId = resp.payload.fields.instance_id.string_value || "";
      }
    }
    if (
      !this._refreshExp ||
      this._refreshExp <= Math.floor(Date.now() / 1000)
    ) {
      this._refreshExp = Math.floor(Date.now() / 1000) + 86400; // 24h fallback
    }

    this._scheduleRenewal();
  }

  /** Exchanges the cached refresh token for an access token. */
  private async _doAccessExchange(): Promise<string> {
    if (!this._exchClient) {
      throw new Error("token exchange client not initialized");
    }

    const resp = await this._exchangeToken({
      input_token: this._refreshTok,
      aud: this._serviceAudience,
    });

    this._current = resp.base64 || "";
    if (resp.payload?.fields) {
      if (resp.payload.fields.exp) {
        this._exp = resp.payload.fields.exp.number_value || 0;
      }
      if (resp.payload.fields.instance_id) {
        this._instanceId = resp.payload.fields.instance_id.string_value || "";
      }
    }
    if (!this._exp || this._exp <= Math.floor(Date.now() / 1000)) {
      this._exp = Math.floor(Date.now() / 1000) + 3600; // 1h fallback
    }

    return this._current;
  }

  /** Constructs a CloudIdentityProof appropriate for the vendor. */
  private async _buildProof(): Promise<CloudIdentityProof> {
    switch (this._vendor) {
      case CloudVendor.AWS:
        return buildAWSCloudProof();
      case CloudVendor.GCP:
        return buildGCPCloudProof(this._serviceAudience);
      case CloudVendor.AZURE:
        return buildAzureCloudProof(this._serviceAudience);
      default:
        throw new Error(`unsupported cloud vendor: ${this._vendor}`);
    }
  }

  /** Converts a CloudIdentityProof to the proto wire format. */
  private _proofToProto(proof: CloudIdentityProof): any {
    const pb: any = { vendor: proof.vendor };
    if (proof.presignedRequest) {
      pb.presigned_request = {
        method: proof.presignedRequest.method,
        url: proof.presignedRequest.url,
        headers: proof.presignedRequest.headers,
        body: proof.presignedRequest.body,
      };
    }
    if (proof.identityToken) {
      pb.identity_token = proof.identityToken;
    }
    return pb;
  }

  /** Calls ExchangeToken RPC via the gRPC client. */
  private _exchangeToken(req: any): Promise<any> {
    return new Promise((resolve, reject) => {
      const deadline = new Date(Date.now() + EXCHANGE_TIMEOUT_MS);
      this._exchClient.exchangeToken(
        req,
        { deadline },
        (err: any, resp: any) => {
          if (err) reject(err);
          else resolve(resp);
        },
      );
    });
  }

  /** Schedules half-life renewal of the refresh token. */
  private _scheduleRenewal(): void {
    if (this._renewTimer) {
      clearTimeout(this._renewTimer);
      this._renewTimer = null;
    }

    const halfLifeSecs = Math.max((this._refreshExp - this._refreshIat) / 2, 0);
    if (halfLifeSecs <= 0) return;

    // Renew at: issued_at + half_life + random(0, half_life)
    const jitterSecs = Math.random() * halfLifeSecs;
    const delaySecs = halfLifeSecs + jitterSecs;
    const delayMs = delaySecs * 1000;

    this._renewTimer = setTimeout(async () => {
      try {
        await this._doCloudExchange();
        console.log("Cloud auth: refresh token renewed at half-life");
      } catch (e) {
        console.warn("Cloud auth: half-life renewal failed", e);
      }
    }, delayMs);

    // Don't prevent Node.js from exiting
    if (
      this._renewTimer &&
      typeof this._renewTimer === "object" &&
      "unref" in this._renewTimer
    ) {
      this._renewTimer.unref();
    }
  }
}

/**
 * Creates gRPC metadata with a cloud-minted bearer token.
 * Skips token injection for TokenExchangerService calls.
 */
export function cloudMinterMetadataInterceptor(
  minter: CloudTokenMinter,
): (options: any, nextCall: any) => any {
  return (options: any, nextCall: any) => {
    // Skip auth for TokenExchangerService calls
    if (options.method_definition?.path?.includes("TokenExchangerService")) {
      return new grpc.InterceptingCall(nextCall(options));
    }

    return new grpc.InterceptingCall(nextCall(options), {
      start: async (metadata: grpc.Metadata, _listener: any, next: any) => {
        try {
          const token = await minter.getToken();
          metadata.set("authorization", `Bearer ${token}`);
        } catch (e) {
          console.error("Failed to obtain cloud bearer token:", e);
        }
        next(metadata, _listener);
      },
    });
  };
}
